//! Mirza's core for the phone apps. The app records the microphone itself and
//! passes the audio in; this crate streams it to the speech-to-text provider
//! through `mirza-core` and hands the recognized text back. It also keeps the
//! app's settings and API keys ([`MirzaCore`]). Voice tasks are in [`tasks`].
//!
//! Exposed through UniFFI. The Kotlin bindings are generated by
//! `android/build-rust.sh`; nothing here is Android-specific, so the crate
//! builds and its tests run on the desktop too.

use std::sync::{Arc, Mutex, OnceLock};

use mirza_core::audio::sound::{self, Sound};
use mirza_core::config::Providers;
use mirza_core::normalize::persian_letters;
use mirza_core::providers::{self, StreamRequest, SttEvent};
use tokio::runtime::Runtime;
use tokio::sync::mpsc;
use tokio::task::JoinHandle;

mod settings;

pub use settings::MobileConfig;

uniffi::setup_scaffolding!();

pub mod tasks;

/// 50 ms chunks waiting to be sent: ten seconds, enough to cover a slow
/// connection while the user already speaks.
const AUDIO_QUEUE: usize = 200;

#[derive(Debug, thiserror::Error, uniffi::Error)]
#[uniffi(flat_error)]
pub enum MobileError {
    #[error("{0}")]
    Settings(String),
    #[error("{0}")]
    Network(String),
}

/// A callback from the app that failed in a way it didn't report itself.
impl From<uniffi::UnexpectedUniFFICallbackError> for MobileError {
    fn from(e: uniffi::UnexpectedUniFFICallbackError) -> Self {
        MobileError::Settings(format!("The app failed: {}", e.reason))
    }
}

/// What a dictation needs to know. Soniox only, for now.
#[derive(Debug, Clone, uniffi::Record)]
pub struct DictationConfig {
    pub api_key: String,
    /// Empty for the default model.
    pub model: String,
    /// Language hints such as ["fa", "en"]; empty for the defaults.
    pub languages: Vec<String>,
    /// "" or "none" for a direct connection, or an http:// or socks5:// URL.
    pub proxy: String,
}

/// Receives a dictation's results. Called from a background thread.
#[uniffi::export(callback_interface)]
pub trait DictationListener: Send + Sync {
    /// Newly settled text, ready to type, with Persian letters fixed.
    fn on_text(&self, text: String);
    /// The provider's current guess for the words after the settled text.
    fn on_partial(&self, text: String);
    /// The dictation failed; the message is in plain words.
    fn on_error(&self, message: String);
    /// All text has been delivered.
    fn on_finished(&self);
}

/// One dictation: audio goes in with [`Dictation::push_audio`], text comes
/// out through the listener.
#[derive(uniffi::Object)]
pub struct Dictation {
    audio: Mutex<Option<mpsc::Sender<Vec<u8>>>>,
    stream: Mutex<Option<JoinHandle<()>>>,
}

#[uniffi::export]
impl Dictation {
    /// Starts connecting right away. Audio pushed before the connection is up
    /// waits in a queue.
    #[uniffi::constructor]
    pub fn new(config: DictationConfig, listener: Box<dyn DictationListener>) -> Result<Arc<Self>, MobileError> {
        let proxy = mirza_core::net::resolve_proxy(if config.proxy.trim().is_empty() { "none" } else { &config.proxy })
            .map_err(|e| MobileError::Settings(e.to_string()))?;
        if config.api_key.trim().is_empty() {
            return Err(MobileError::Settings("Enter your Soniox API key first.".into()));
        }
        let mut settings = Providers::default().soniox;
        if !config.model.trim().is_empty() {
            settings.model = config.model.trim().to_owned();
        }
        if !config.languages.is_empty() {
            settings.languages = config.languages;
        }
        let req =
            StreamRequest { provider: "soniox".into(), api_key: config.api_key.trim().to_owned(), settings, proxy };
        Ok(Self::start(req, listener))
    }

    /// Queues a chunk of 16-bit little-endian mono audio at [`sample_rate`].
    /// Returns false if it was dropped: the dictation has ended or the queue
    /// is full.
    pub fn push_audio(&self, pcm: Vec<u8>) -> bool {
        let audio = self.audio.lock().unwrap_or_else(|e| e.into_inner());
        audio.as_ref().is_some_and(|tx| tx.try_send(pcm).is_ok())
    }

    /// No more audio: the provider sends the rest of the text, then the
    /// listener gets `on_finished`.
    pub fn finish(&self) {
        self.audio.lock().unwrap_or_else(|e| e.into_inner()).take();
    }

    /// Stops at once; the listener hears nothing more.
    pub fn cancel(&self) {
        self.finish();
        if let Some(stream) = self.stream.lock().unwrap_or_else(|e| e.into_inner()).take() {
            stream.abort();
        }
    }
}

impl Dictation {
    fn start(req: StreamRequest, listener: Box<dyn DictationListener>) -> Arc<Self> {
        let (audio_tx, audio_rx) = mpsc::channel(AUDIO_QUEUE);
        let (events_tx, events_rx) = mpsc::unbounded_channel();
        let rt = runtime();
        let _ctx = rt.enter();
        let stream = providers::start(req, audio_rx, events_tx);
        rt.spawn(forward(events_rx, listener));
        Arc::new(Self { audio: Mutex::new(Some(audio_tx)), stream: Mutex::new(Some(stream)) })
    }
}

impl Drop for Dictation {
    fn drop(&mut self) {
        self.cancel();
    }
}

/// The sample rate the audio must have (Soniox; the app asks [`MirzaCore::sample_rate`]).
#[uniffi::export]
pub fn sample_rate() -> u32 {
    providers::sample_rate("soniox")
}

/// The app's side of the core: its settings, its API keys, and dictation with them.
#[derive(uniffi::Object)]
pub struct MirzaCore {
    store: settings::Store,
    config: Mutex<MobileConfig>,
    problem: Option<String>,
}

/// A newer release than this app.
#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct Release {
    pub version: String,
    /// Its page on GitHub, with the download.
    pub url: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum SoundKind {
    Start,
    Stop,
    Error,
}

#[uniffi::export]
impl MirzaCore {
    /// Settings and keys live in `dir`, the app's private files.
    #[uniffi::constructor]
    pub fn new(dir: String) -> Arc<Self> {
        let store = settings::Store::new(dir);
        let (config, problem) = store.load();
        Arc::new(Self { store, config: Mutex::new(config), problem })
    }

    /// Why the saved settings couldn't be used, once, after a start with a broken file.
    pub fn config_problem(&self) -> Option<String> {
        self.problem.clone()
    }

    /// Every setting, defaults included, as JSON.
    pub fn config_json(&self) -> String {
        serde_json::to_string(&self.config()).unwrap_or_default()
    }

    /// Changes one setting, e.g. `set_value("providers.soniox.languages", "[\"fa\"]")`; "null"
    /// puts it back to the default. A value that doesn't fit is refused with a reason.
    pub fn set_value(&self, path: String, json: String) -> Result<(), MobileError> {
        let value: serde_json::Value =
            serde_json::from_str(&json).map_err(|e| MobileError::Settings(format!("{path}: {e}")))?;
        let cfg = self.store.set(&path, &value)?;
        *self.config.lock().unwrap_or_else(|e| e.into_inner()) = cfg;
        Ok(())
    }

    /// Whether a key is saved for a service ("soniox", "claude"...). Keys never leave the core.
    pub fn key_set(&self, service: String) -> bool {
        self.store.key(&service).is_some()
    }

    /// Saves a service's API key; an empty one removes it.
    pub fn set_key(&self, service: String, key: String) -> Result<(), MobileError> {
        self.store.set_key(&service, &key)
    }

    /// The sample rate the chosen speech service wants.
    pub fn sample_rate(&self) -> u32 {
        providers::sample_rate(&self.config().active_provider)
    }

    /// Starts a dictation with the saved settings and key. It connects right away; audio pushed
    /// before the connection is up waits.
    pub fn dictate(&self, listener: Box<dyn DictationListener>) -> Result<Arc<Dictation>, MobileError> {
        let cfg = self.config();
        let provider = cfg.active_provider.clone();
        let api_key = self.store.key(&provider).ok_or_else(|| settings::missing_key(&provider))?;
        let proxy = mirza_core::net::resolve_proxy(&cfg.proxy).map_err(|e| MobileError::Settings(e.to_string()))?;
        let settings = cfg.providers.get(&provider).cloned().unwrap_or_else(|| cfg.providers.soniox.clone());
        Ok(Dictation::start(StreamRequest { provider, api_key, settings, proxy }, listener))
    }

    /// Asks GitHub for the latest release, through the proxy setting; None when this app is the
    /// newest. Blocks, so call it off the main thread.
    pub fn newer_release(&self) -> Result<Option<Release>, MobileError> {
        let proxy =
            mirza_core::net::resolve_proxy(&self.config().proxy).map_err(|e| MobileError::Settings(e.to_string()))?;
        let latest = runtime().block_on(mirza_core::update::latest(proxy.as_ref())).map_err(MobileError::Network)?;
        Ok(mirza_core::update::is_newer(&latest.version, mirza_core::update::VERSION)
            .then_some(Release { version: latest.version, url: latest.url }))
    }
}

impl MirzaCore {
    fn config(&self) -> MobileConfig {
        self.config.lock().unwrap_or_else(|e| e.into_inner()).clone()
    }
}

/// The start, stop and error sounds the desktop plays, as WAV files, at `volume` (0 to 100).
#[uniffi::export]
pub fn sound_wav(kind: SoundKind, volume: u8) -> Vec<u8> {
    let sound = match kind {
        SoundKind::Start => Sound::Start,
        SoundKind::Stop => Sound::Stop,
        SoundKind::Error => Sound::Error,
    };
    sound::wav(sound, volume)
}

/// The version of Mirza's core, for the about screen and bug reports.
#[uniffi::export]
pub fn core_version() -> String {
    env!("CARGO_PKG_VERSION").to_owned()
}

/// Passes the provider's events to the listener until the stream ends.
async fn forward(mut events: mpsc::UnboundedReceiver<SttEvent>, listener: Box<dyn DictationListener>) {
    while let Some(ev) = events.recv().await {
        match ev {
            SttEvent::Final(text) => listener.on_text(persian_letters(&text)),
            SttEvent::Partial(text) => listener.on_partial(persian_letters(&text)),
            SttEvent::Heard => {}
            SttEvent::Finished => return listener.on_finished(),
            SttEvent::Error(message) => return listener.on_error(message),
        }
    }
}

/// One small runtime for every dictation in the process.
fn runtime() -> &'static Runtime {
    static RT: OnceLock<Runtime> = OnceLock::new();
    RT.get_or_init(|| {
        tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_name("mirza-core")
            .enable_all()
            .build()
            .expect("starting the tokio runtime")
    })
}

#[cfg(test)]
mod tests {
    use std::time::Duration;

    use super::*;

    #[derive(Debug, Clone, PartialEq)]
    enum Heard {
        Text(String),
        Partial(String),
        Error(String),
        Finished,
    }

    struct Recorder(std::sync::mpsc::Sender<Heard>);

    impl DictationListener for Recorder {
        fn on_text(&self, text: String) {
            let _ = self.0.send(Heard::Text(text));
        }
        fn on_partial(&self, text: String) {
            let _ = self.0.send(Heard::Partial(text));
        }
        fn on_error(&self, message: String) {
            let _ = self.0.send(Heard::Error(message));
        }
        fn on_finished(&self) {
            let _ = self.0.send(Heard::Finished);
        }
    }

    fn config(proxy: &str) -> DictationConfig {
        DictationConfig { api_key: "k".into(), model: String::new(), languages: Vec::new(), proxy: proxy.into() }
    }

    #[tokio::test]
    async fn text_keeps_half_spaces_and_gets_persian_letters() {
        let (tx, rx) = std::sync::mpsc::channel();
        let (etx, erx) = mpsc::unbounded_channel();
        etx.send(SttEvent::Heard).unwrap();
        etx.send(SttEvent::Final("مي\u{200c}خواهم test كنم".into())).unwrap();
        etx.send(SttEvent::Partial(" بعدي".into())).unwrap();
        etx.send(SttEvent::Finished).unwrap();
        etx.send(SttEvent::Final("after the end".into())).unwrap();
        forward(erx, Box::new(Recorder(tx))).await;
        let heard: Vec<Heard> = rx.try_iter().collect();
        assert_eq!(
            heard,
            [Heard::Text("می\u{200c}خواهم test کنم".into()), Heard::Partial(" بعدی".into()), Heard::Finished]
        );
    }

    #[test]
    fn bad_settings_are_refused() {
        let (tx, _rx) = std::sync::mpsc::channel();
        let err = Dictation::new(config("ftp://proxy"), Box::new(Recorder(tx.clone()))).err().unwrap();
        assert!(err.to_string().contains("proxy"), "{err}");
        let no_key = DictationConfig { api_key: " ".into(), ..config("") };
        assert!(Dictation::new(no_key, Box::new(Recorder(tx))).is_err());
    }

    #[test]
    fn dictation_needs_the_saved_key() {
        let dir = std::env::temp_dir().join(format!("mirza-mobile-core-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let core = MirzaCore::new(dir.to_string_lossy().into_owned());
        assert!(core.config_problem().is_none());
        let (tx, _rx) = std::sync::mpsc::channel();
        let err = core.dictate(Box::new(Recorder(tx.clone()))).err().unwrap().to_string();
        assert!(err.contains("Soniox API key"), "{err}");

        core.set_key("soniox".into(), "k".into()).unwrap();
        assert!(core.key_set("soniox".into()));
        assert!(!core.config_json().contains("\"k\""), "keys stay out of the settings");
        core.set_value("active_provider".into(), "\"openai\"".into()).unwrap();
        assert_eq!(core.sample_rate(), 24_000);
        assert!(core.dictate(Box::new(Recorder(tx.clone()))).err().unwrap().to_string().contains("OpenAI"));
        core.set_value("active_provider".into(), "null".into()).unwrap();
        assert_eq!(core.sample_rate(), 16_000);
        assert!(core.set_value("sounds".into(), "not json".into()).is_err());

        let json: serde_json::Value = serde_json::from_str(&core.config_json()).unwrap();
        assert_eq!(json["providers"]["soniox"]["model"], "stt-rt-v6");
        assert_eq!(json["bubble"]["show"], true);
        // A port nothing listens on: the dictation starts and then reports the failure.
        let port = std::net::TcpListener::bind("127.0.0.1:0").unwrap().local_addr().unwrap().port();
        core.set_value("proxy".into(), format!("\"http://127.0.0.1:{port}\"")).unwrap();
        let (tx, rx) = std::sync::mpsc::channel();
        let d = core.dictate(Box::new(Recorder(tx))).unwrap();
        assert!(matches!(rx.recv_timeout(Duration::from_secs(30)).unwrap(), Heard::Error(_)));
        d.cancel();
        let _ = std::fs::remove_dir_all(dir);
    }

    #[test]
    fn sounds_are_wav_files() {
        let wav = sound_wav(SoundKind::Start, 50);
        assert_eq!(&wav[..4], b"RIFF");
        assert!(wav.len() > 1000);
    }

    #[test]
    fn connection_errors_reach_the_listener() {
        // A proxy port nothing listens on: the connection is refused at once.
        let port = std::net::TcpListener::bind("127.0.0.1:0").unwrap().local_addr().unwrap().port();
        let (tx, rx) = std::sync::mpsc::channel();
        let d = Dictation::new(config(&format!("http://127.0.0.1:{port}")), Box::new(Recorder(tx))).unwrap();
        assert!(d.push_audio(vec![0; 1600]));
        match rx.recv_timeout(Duration::from_secs(30)).unwrap() {
            Heard::Error(e) => assert!(e.contains("Check that your proxy is working"), "{e}"),
            other => panic!("expected an error, got {other:?}"),
        }
        d.finish();
        assert!(!d.push_audio(vec![0; 1600]), "no audio after finish");
    }
}
